{
  "items": [
    {
      "name": "Behrend.bound_aux'",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ (n d : ℕ), ↑(d ^ n) / ↑(n * d ^ 2) ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    },
    {
      "name": "Nat.choose_le_pow_div",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Semifield α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α] (r n : ℕ),\n  ↑(n.choose r) ≤ ↑n ^ r / ↑r.factorial"
    },
    {
      "name": "Behrend.bound_aux",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {n d : ℕ}, d ≠ 0 → 2 ≤ n → ↑d ^ (n - 2) / ↑n ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    },
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    },
    {
      "name": "Nat.pow_le_choose",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Semifield α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α] (r n : ℕ),\n  ↑(n + 1 - r) ^ r / ↑r.factorial ≤ ↑(n.choose r)"
    }
  ]
}
